    query: GetFilterMaterialsQueryDto,
  ): Promise<Array<{ code: string }>> {
    const parameters = new URLSearchParams({ plant: String(query.plant) });
    if (query.search !== undefined && query.search !== '') {
      parameters.set('search', query.search);
    }
    if (query.equipment !== undefined && query.equipment !== '') {
      parameters.set('equipment', query.equipment);
    }
    const path = `isa95-operation-model/operation-definitions/filter-materials?${parameters.toString()}`;
    try {
      const result = await this.daprClient.invoker.invoke(
        this.daprConfigService.masterApiAppId,
        path,
        HttpMethod.GET,
      );
      this.logger.log(`Fetched filter-materials for plant ${query.plant}`);
      return result as Array<{ code: string }>;
    }
    catch (error) {
      this.logger.error(
        `Failed to fetch filter-materials for plant ${query.plant}`,
        error instanceof Error ? error.message : String(error),
