  ): Promise<Array<OperationSegmentByMaterialRowDto>> {
    const parameters = new URLSearchParams({
      plant: String(query.plant),
      material: query.material,
    });
    const path = `isa95-operation-model/operation-segments/by-material?${parameters.toString()}`;
    try {
      const result = await this.daprClient.invoker.invoke(
        this.daprConfigService.masterApiAppId,
        path,
        HttpMethod.GET,
      );
      this.logger.log(
        `Fetched operation segments by material ${query.material} for plant ${query.plant}`,
      );
      return result as Array<OperationSegmentByMaterialRowDto>;
    }
    catch (error) {
      this.logger.error(
        `Failed to fetch operation segments by material ${query.material}`,
        error instanceof Error ? error.message : String(error),
      );
      return [];
    }
  }

  public async getOperationSegmentDetails(
    operationNumber: string,
  ): Promise<OperationSegmentDetailsDto | null> {
    const path = `isa95-operation-model/operation-segments/${encodeURIComponent(operationNumber)}`;
    try {
      const result = await this.daprClient.invoker.invoke(
        this.daprConfigService.masterApiAppId,
        path,
        HttpMethod.GET,
      );
      this.logger.log(
        `Fetched operation segment details for operationNumber ${operationNumber}`,
      );
      return result as OperationSegmentDetailsDto;
    }
    catch (error) {
      this.logger.error(
        `Failed to fetch operation segment details for operationNumber ${operationNumber}`,
        error instanceof Error ? error.message : String(error),
      );
      return null;
    }
  }
